using System.Text.Json;
using Microsoft.AspNetCore.Mvc;
using OnlineStore.Data;
using OnlineStore.Models;
using OnlineStore.ViewModels;
namespace OnlineStore.Controllers;
public class CartController(StoreContext db) : Controller { const string CartKey = "cart"; List<CartItem> GetCart() => JsonSerializer.Deserialize<List<CartItem>>(HttpContext.Session.GetString(CartKey) ?? "[]") ?? []; void Save(List<CartItem> cart) => HttpContext.Session.SetString(CartKey, JsonSerializer.Serialize(cart)); public IActionResult Index() => View(new CartViewModel { Items = GetCart() }); [HttpPost] public async Task<IActionResult> AddToCart(int productId) { var p = await db.Products.FindAsync(productId); if (p is null || p.StockQuantity < 1) return NotFound(); var cart = GetCart(); var item = cart.FirstOrDefault(x => x.ProductId == productId); if (item is null) cart.Add(new CartItem { ProductId=p.Id, Name=p.Name, Price=p.Price, ImageUrl=p.ImageUrl, Quantity=1 }); else if (item.Quantity < p.StockQuantity) item.Quantity++; Save(cart); TempData["Message"] = "Product added to cart."; return Redirect(Request.Headers.Referer.ToString() ?? "/Products"); } [HttpPost] public IActionResult Increase(int productId) { var cart=GetCart(); var item=cart.FirstOrDefault(x=>x.ProductId==productId); if(item is not null) { item.Quantity++; Save(cart); } return RedirectToAction(nameof(Index)); } [HttpPost] public IActionResult Decrease(int productId) { var cart=GetCart(); var item=cart.FirstOrDefault(x=>x.ProductId==productId); if(item is not null) { item.Quantity--; if(item.Quantity<=0) cart.Remove(item); Save(cart); } return RedirectToAction(nameof(Index)); } [HttpPost] public IActionResult Remove(int productId) { var cart=GetCart(); cart.RemoveAll(x=>x.ProductId==productId); Save(cart); return RedirectToAction(nameof(Index)); } [HttpPost] public IActionResult Clear() { Save([]); return RedirectToAction(nameof(Index)); } }
